import * as d3 from 'd3';
import moment from 'moment';
import { seconds_to_duration } from '../util/time';
import { getColorFromString, getCategoryColorFromEvent } from '~/util/color';
// Dimensions of sunburst.
const width = 750;
const height = 600;
const radius = Math.min(width, height) / 2;
const legendData = {
    afk: getColorFromString('afk'),
    'not-afk': getColorFromString('not-afk'),
    hibernating: getColorFromString('hibernating'),
};
let rootEl; // The root DOM node of the graph as a d3 object
let vis; // The root SVG node of the graph as a d3 object
let partition_layout; // The partition layout
let arc;
function drawLegend() {
    // Dimensions of legend item: width, height, spacing, radius of rounded rect.
    const li = {
        w: 75,
        h: 30,
        s: 3,
        r: 3,
    };
    const legend = d3
        .select('.legend')
        .append('svg:svg')
        .attr('width', li.w)
        .attr('height', Object.keys(legendData).length * (li.h + li.s));
    const g = legend
        .selectAll('g')
        .data(Object.entries(legendData).map(t => {
        return { key: t[0], value: t[1] };
    }))
        .enter()
        .append('svg:g')
        .attr('transform', function (d, i) {
        return 'translate(0,' + i * (li.h + li.s) + ')';
    });
    g.append('svg:rect')
        .attr('rx', li.r)
        .attr('ry', li.r)
        .attr('width', li.w)
        .attr('height', li.h)
        .style('fill', function (d) {
        return d.value;
    });
    g.append('svg:text')
        .attr('x', li.w / 2)
        .attr('y', li.h / 2)
        .attr('dy', '0.35em')
        .attr('text-anchor', 'middle')
        .text(function (d) {
        return d.key;
    });
}
function drawClockTick(a) {
    const xn = Math.cos(a);
    const yn = Math.sin(a);
    vis
        .append('line')
        .attr('x1', 170 * xn)
        .attr('y1', 170 * yn)
        .attr('x2', 155 * xn)
        .attr('y2', 155 * yn)
        .style('stroke', '#CCC')
        .style('stroke-width', 1);
}
function drawClock(h, m, text) {
    const a = 2 * Math.PI * (h / 24 + m / 24 / 60) - (1 / 2) * Math.PI;
    drawClockTick(a);
    const xn = Math.cos(a);
    const yn = Math.sin(a);
    vis
        .append('text')
        .text(text || moment({ hours: h }).format('HH:mm'))
        .attr('text-anchor', 'middle')
        .attr('font-size', '1.2em')
        //.attr("font-weight", "bold")
        .style('fill', '#999')
        .attr('x', 130 * xn)
        .attr('y', 5 + 140 * yn);
}
function mouseclick(_, d) {
    console.log('Clicked', d);
}
function showInfo(d) {
    const hoverEl = d3.select('.explanation > .hover');
    const e = d.data;
    const m = moment(e.timestamp);
    hoverEl.select('.date').text(m.format('YYYY-MM-DD'));
    hoverEl.select('.time').text(m.format('HH:mm:ss'));
    const durationString = seconds_to_duration(e.duration);
    hoverEl.select('.duration').text(durationString);
    hoverEl.select('.title').text(e.data.app || e.data.status);
    hoverEl.select('.data').text(e.data.title || '');
    d3.select('.explanation > .base').style('display', 'none');
    hoverEl.style('visibility', '');
}
// Fade all but the current sequence, and show it in the breadcrumb trail.
function mouseover(_, d) {
    showInfo(d);
    const sequenceArray = d.ancestors().reverse();
    sequenceArray.shift(); // remove root node from the array
    // Fade all the segments.
    rootEl.selectAll('path').style('opacity', 0.5);
    // Then highlight only those that are an ancestor of the current segment.
    // FIXME: This currently makes all other svg paths on the page faded as well
    rootEl
        .selectAll('path')
        .filter(function (node) {
        // Split DST arcs share event data; highlight every fragment and its parents.
        return sequenceArray.some(ancestor => ancestor.data === node.data);
    })
        .style('opacity', 1);
}
// Restore everything to full opacity when moving off the visualization.
function mouseleave() {
    // Deactivate all segments during transition.
    rootEl.selectAll('path').on('mouseover', null);
    // Transition each segment to full opacity and then reactivate it.
    rootEl
        .selectAll('path')
        .transition()
        .duration(100)
        .style('opacity', 1)
        .on('end', function () {
        d3.select(this).on('mouseover', mouseover);
    });
    rootEl.select('.explanation > .base').style('display', '');
    rootEl.select('.explanation > .hover').style('visibility', 'hidden');
}
function initializeBreadcrumbTrail() {
    // Add the svg area.
    const trail = d3
        .select('.sequence')
        .append('svg:svg')
        .attr('width', width)
        .attr('height', 50)
        .attr('id', 'trail');
    // Add the label at the end, for the percentage.
    trail.append('svg:text').attr('id', 'endlabel').style('fill', '#000');
}
function create(el) {
    // Clear the svg in case we are redrawing
    rootEl = d3.select(el);
    rootEl.selectAll('svg').remove();
    vis = rootEl
        .append('svg:svg')
        .attr('width', width)
        .attr('height', height)
        .append('svg:g')
        .attr('id', 'container')
        .attr('transform', 'translate(' + width / 2 + ',' + height / 2 + ')');
    drawLegend();
    partition_layout = d3.partition().size([2 * Math.PI, radius * radius]);
    arc = d3
        .arc()
        .startAngle(function (d) {
        return d.x0;
    })
        .endAngle(function (d) {
        return d.x1;
    })
        .innerRadius(function (d) {
        return Math.sqrt(d.y0);
    })
        .outerRadius(function (d) {
        return Math.sqrt(d.y1);
    });
}
// Find timezone transitions once per displayed day, not once per event. Split
// there so spring gaps stay empty and repeated fall hours share a clock sector.
function offsetTransitions(start, end) {
    const transitions = [];
    for (let from = start; from < end; from += 3600000) {
        let low = from;
        let high = Math.min(from + 3600000, end);
        const offset = moment(low).utcOffset();
        if (moment(high).utcOffset() === offset)
            continue;
        while (high - low > 1) {
            const middle = Math.floor((low + high) / 2);
            if (moment(middle).utcOffset() === offset)
                low = middle;
            else
                high = middle;
        }
        if (high < end)
            transitions.push(high);
    }
    return transitions;
}
function wallClockAngle(timestamp) {
    const local = moment(timestamp);
    const seconds = local.hours() * 3600 + local.minutes() * 60 + local.seconds() + local.milliseconds() / 1000;
    return (2 * Math.PI * seconds) / 86400;
}
// Main function to draw and set up the visualization, once we have the data.
function update(el, root_event, startOfDay) {
    // Basic setup of page elements.
    initializeBreadcrumbTrail();
    el.querySelector('#container').innerHTML = '';
    // Bounding circle underneath the sunburst, to make it easier to detect
    // when the mouse leaves the parent g.
    vis.append('svg:circle').attr('r', radius).style('opacity', 0);
    // Turn the data into a d3 hierarchy and calculate the sums.
    let root = d3.hierarchy(root_event);
    const root_node = partition_layout(root);
    const mode_clock = true;
    // 0.001 radians is about 14 seconds on the fixed 24-hour dial.
    const threshold = 0.001;
    let nodes;
    if (mode_clock) {
        // TODO: Make this a checkbox in the UI
        const show_whole_day = true;
        let root_start = moment(root_event.timestamp);
        let root_end = root_start.clone().add(root_event.duration, 'seconds');
        if (show_whole_day) {
            // Use the provided start-of-day (which respects the user's startOfDay setting)
            // so that events between midnight and the startOfDay offset are shown correctly.
            // Fall back to calendar midnight if no startOfDay is provided.
            if (startOfDay) {
                root_start = startOfDay.clone();
            }
            else {
                root_start = root_start.startOf('day');
            }
            root_end = root_start.clone().add(1, 'days');
            // Draw clock ticks at standard 6-hour intervals (00, 06, 12, 18)
            for (const h of [0, 6, 12, 18]) {
                drawClock(h, 0);
            }
            // Draw a special marker for the start-of-day boundary if it's not at midnight
            const start_hour = root_start.hours();
            const start_min = root_start.minutes();
            if (start_hour !== 0 || start_min !== 0) {
                drawClock(start_hour, start_min, `${root_start.format('HH:mm')} ☀`);
            }
            // Only mark "Now" when the current instant falls inside the displayed
            // day, so historical and future periods get no marker. Start-inclusive,
            // end-exclusive against the whole-day bounds computed above.
            const now = moment();
            if (!now.isBefore(root_start) && now.isBefore(root_end)) {
                drawClock(now.hour(), now.minute(), 'Now');
            }
        }
        const periodStart = root_start.valueOf();
        const periodEnd = root_end.valueOf();
        const transitions = offsetTransitions(periodStart, periodEnd);
        nodes = root_node.descendants().flatMap(d => {
            const timestamp = moment(d.data.timestamp).valueOf();
            const start = Math.max(periodStart, timestamp);
            const end = Math.min(periodEnd, timestamp + d.data.duration * 1000);
            // Apply visibility to the whole clipped event, not each DST fragment.
            if (!((2 * Math.PI * (end - start)) / 86400000 > threshold))
                return [];
            const bounds = [start, ...transitions.filter(t => t > start && t < end), end];
            return bounds.slice(0, -1).map((from, i) => {
                const x0 = wallClockAngle(from);
                // Each segment has a constant UTC offset. Elapsed duration therefore
                // equals wall-clock duration here. Keep angles unwrapped over midnight;
                // D3 draws the small crossing arc rather than a backwards/full-day arc.
                const x1 = x0 + (2 * Math.PI * (bounds[i + 1] - from)) / 86400000;
                return Object.assign(Object.create(Object.getPrototypeOf(d)), d, { x0, x1 });
            });
        });
    }
    else {
        root = root
            .sum(d => d.duration)
            .sort((a, b) => JSON.stringify(a.data.data).localeCompare(JSON.stringify(b.data.data)));
        // For efficiency, filter nodes to keep only those large enough to see.
        nodes = root_node.descendants().filter(d => d.x1 - d.x0 > threshold);
    }
    vis
        .data([root_event])
        .selectAll('path')
        .data(nodes)
        .enter()
        .append('svg:path')
        .attr('display', function (d) {
        return d.depth ? null : 'none';
    })
        .attr('d', arc)
        .attr('fill-rule', 'evenodd')
        .style('fill', function (d) {
        const e = d.data;
        return d.depth === 2
            ? getCategoryColorFromEvent({ type: 'currentwindow' }, e)
            : getColorFromString(e.data.status || e.data.app);
    })
        .style('opacity', 1)
        .on('mouseover', mouseover)
        .on('click', mouseclick);
    // Add the mouseleave handler to the bounding circle.
    d3.select('#container').on('mouseleave', mouseleave);
}
// NOTE: The original version of this sunburst contained a buildHierarchy
//       function that's not used in our version.
export default {
    create: create,
    update: update,
};
